from decimal import Decimal
from ledgerly import audit
from ledgerly.adjustments import issue_credit_note
from ledgerly.errors import BillingError
from ledgerly.models import Invoice, LineItem

def inv(status="issued", price="50.00"):
    return Invoice("inv_1","cus_1",lines=[LineItem("Seat",1,Decimal(price))],status=status)

# float input
print(issue_credit_note(inv(), 10.5, "goodwill"))
# non-positive
for a in ["0", "-1"]:
    try: issue_credit_note(inv(), a, "x")
    except BillingError as e: print("err", e.code)
# exceeds
try: issue_credit_note(inv(), "50.01", "x")
except BillingError as e: print("err", e.code)
# not issued
try: issue_credit_note(inv("draft"), "1", "x")
except BillingError as e: print("err", e.code)
# approval
try: issue_credit_note(inv(price="600.00"), "501.00", "x")
except BillingError as e: print("err", e.code)
print(issue_credit_note(inv(price="600.00"), "501.00", "x", approved_by="mgr"))
# idempotency
audit.clear()
r1 = issue_credit_note(inv(), "10", "x", idempotency_key="k1")
r2 = issue_credit_note(inv(), "10", "x", idempotency_key="k1")
print(r1, r2, len(audit.events("credit_note_issued")))
EOF"}

